customModelExample:
const models = {
  PurchaseOrderModel: {
    transformer: (data) => ({
      // Add approval status badge text
      approvalStatusDisplay: data?.status === 'PENDING' ? 'Awaiting Approval' : 
                            data?.status === 'APPROVED' ? 'Approved - Ready to Order' : 
                            data?.status,
      // Add formatted approval flow summary
      approvalSummary: data?.approvalFlow?.map(rule => 
        `${rule.ruleName}: ${rule.events?.length || 0} events`
      ).join(', '),
      // Add created by full name
      createdByName: data?.createdBy ? 
        `${data.createdBy.firstname} ${data.createdBy.lastname}` : null,
    }),
  },
};

await initializers.mountImmediately(initialize, { models });

PurchaseOrderModel.definition:
interface PurchaseOrderModel {
  typename: string;
  uid: string;
  number: string;
  status: string;
  availableActions: string[];
  approvalFlow:
    | {
        ruleName: string;
        events: Array<{
          message: string;
          name: string;
          role: string;
          status: string;
          updatedAt: string;
        }>;
      }[]
    | [];
  comments?: Array<{
    uid: string;
    createdAt: string;
    author: {
      firstname: string;
      lastname: string;
      email: string;
    };
    text: string;
  }>;
  createdAt: string;
  updatedAt: string;
  createdBy: {
    firstname: string;
    lastname: string;
    email: string;
  };
  historyLog?: Array<{
    activity: string;
    createdAt: string;
    message: string;
    uid: string;
  }>;
  quote: QuoteProps | null;
  order: {
    orderNumber: string;
    id: string;
  };
}
